<template>
  <section class="progress-panel">
    <p class="eyebrow">DIARIO DE VIAJE</p><h3>Tu progreso estelar</h3>
    <div class="summary"><div><strong>{{ completados.length }}/5</strong><span>Evaluaciones completadas</span></div><div><strong>{{ puntos }}</strong><span>Puntos de evaluación</span></div><div><strong>{{ porcentaje }}%</strong><span>Avance de evaluación</span></div></div>
    <div class="progress-track"><span :style="{width:`${porcentaje}%`}"></span></div>
    <h4 class="list-heading">Avance de actividades</h4>
    <p class="section-description">{{ actividadesRealizadasTotal }}/{{ totalActividades }} actividades realizadas y {{ actividadesCompletadas }} superadas.</p>
    <ul class="progress-list"><li v-for="mundo in mundos" :key="mundo.id"><span>{{ mundo.icono }} {{ mundo.titulo }}</span><b>{{ contarActividadesRealizadas(mundo) }}/{{ mundo.actividades.length }} realizadas · {{ contarActividades(mundo) }} superadas</b></li></ul>
    <h4 class="list-heading">Resultados de evaluaciones</h4>
    <ul class="progress-list"><li v-for="mundo in mundos" :key="mundo.id"><span>{{ mundo.icono }} {{ mundo.titulo }}</span><b v-if="registro[mundo.id] !== undefined">{{ registro[mundo.id] }}/10</b><span v-else class="pending">Pendiente</span></li></ul>
    <div v-if="completados.length===5" class="award"><span>🏆</span><strong>¡Explorador/a de AstroMat!</strong><p>Has completado las cinco misiones matemáticas. ¡La galaxia celebra tu esfuerzo!</p><div class="congratulations"><span class="congratulations-astronaut" role="img" aria-label="Astronauta felicitándote">🧑‍🚀</span><strong>¡Felicidades! ¡Lo lograste!</strong><span class="celebration-stars" aria-hidden="true">✨ ⭐ ✨</span></div></div>
    <button v-if="completados.length || actividadesRealizadasTotal || totalEstrellas" type="button" class="reset-progress" @click="reiniciarAvance">↺ Reiniciar avance</button>
  </section>
</template>
<script setup>
import {computed} from 'vue'
const props=defineProps({mundos:{type:Array,required:true},registro:{type:Object,default:()=>({})},progresoActividades:{type:Object,default:()=>({})},actividadesRealizadas:{type:Object,default:()=>({})},estrellas:{type:Object,default:()=>({})}})
const emit=defineEmits(['reiniciar'])
const completados=computed(()=>props.mundos.filter(m=>props.registro[m.id]!==undefined))
const puntos=computed(()=>Object.values(props.registro).reduce((a,b)=>a+b,0))
const porcentaje=computed(()=>Math.round(completados.value.length/5*100))
const totalActividades=computed(()=>props.mundos.reduce((total,mundo)=>total+mundo.actividades.length,0))
const actividadesCompletadas=computed(()=>props.mundos.reduce((total,mundo)=>total+contarActividades(mundo),0))
const actividadesRealizadasTotal=computed(()=>props.mundos.reduce((total,mundo)=>total+contarActividadesRealizadas(mundo),0))
const totalEstrellas=computed(()=>Object.values(props.estrellas).reduce((total,cantidad)=>total+cantidad,0))

function contarActividades(mundo) {
  const completadas=props.progresoActividades[mundo.id] || {}
  return mundo.actividades.filter(actividad=>completadas[actividad.id]).length
}

function contarActividadesRealizadas(mundo) {
  const realizadas=props.actividadesRealizadas[mundo.id] || {}
  return mundo.actividades.filter(actividad=>realizadas[actividad.id]).length
}

function reiniciarAvance() {
  if (window.confirm('¿Deseas reiniciar todo el avance? Se borrarán las puntuaciones de actividades y evaluaciones, y las estrellas ganadas.')) {
    emit('reiniciar')
  }
}
</script>
<style scoped>
