x) rotate(-12deg)}to{transform:translateY(-7px) rotate(12deg)}}@keyframes star-sparkle{from{opacity:.55;transform:scale(.85)}to{opacity:1;transform:scale(1.15)}}@keyframes celebration-glow{0%,100%{box-shadow:0 0 0 #ffe3a000}50%{box-shadow:0 0 24px #ffe3a033}}.reset-progress{display:block;margin:18px auto 0;padding:10px 16px;border:1px solid #ff9da888;border-radius:12px;background:#ff73801f;color:#ffdfe3;font-weight:900;cursor:pointer;transition:.2s}.reset-progress:hover{background:#ff738044;border-color:#ffc3c9;transform:translateY(-2px)}@media(prefers-reduced-motion:reduce){.congratulations,.congratulations-astronaut,.celebration-stars{animation:none}}
</style>
