<template>
  <section class="activity">
    <div class="section-title"><span>🧪</span><div><p class="eyebrow">LABORATORIO DE PRÁCTICA</p><h3>Completa las cinco actividades</h3></div></div>
    <p class="intro">Cada respuesta correcta suma un punto a tus actividades y una estrella. Puedes volver a intentar las que aún no superas.</p>
    <div class="activity-list">
      <article v-for="(actividad,index) in actividades" :key="actividad.id" class="mission-card">
        <h4>Actividad {{ index + 1 }} de {{ actividades.length }}</h4>
        <p class="question">{{ actividad.pregunta }}</p>
        <form class="answer-row" @submit.prevent="comprobar(actividad)">
          <label class="sr-only" :for="`respuesta-${mundoId}-${actividad.id}`">Tu respuesta para la actividad {{ index + 1 }}</label>
          <input
            :id="`respuesta-${mundoId}-${actividad.id}`"
            v-model="respuestas[actividad.id]"
            type="number"
            inputmode="numeric"
            placeholder="Escribe tu respuesta"
            :disabled="completadas[actividad.id] || resultados[actividad.id] !== undefined"
          >
          <button type="submit" :disabled="respuestas[actividad.id] === undefined || respuestas[actividad.id] === '' || completadas[actividad.id] || resultados[actividad.id] !== undefined">Comprobar</button>
        </form>
        <Transition name="feedback-pop">
          <div v-if="completadas[actividad.id] || resultados[actividad.id] !== undefined" class="feedback" :class="{correct: completadas[actividad.id] || resultados[actividad.id]}">
            <strong>{{ completadas[actividad.id] || resultados[actividad.id] ? '¡Actividad superada! ⭐' : '¡Sigue intentando! 🚀' }}</strong>
            <p>{{ completadas[actividad.id] || resultados[actividad.id] ? 'Respuesta correcta: sumaste un punto y una estrella.' : `La respuesta correcta es ${actividad.respuesta}.` }} {{ actividad.ayuda }}</p>
            <button v-if="!completadas[actividad.id] && resultados[actividad.id] === false" type="button" @click="reiniciar(actividad.id)">Volver a intentar</button>
          </div>
        </Transition>
      </article>
    </div>
  </section>
</template>
<script setup>
import { ref, watch } from 'vue'
import { useCompletionSound } from '../composables/useCompletionSound'
const { playCompletionSound } = useCompletionSound()
const emit = defineEmits(['calificada'])
const props=defineProps({actividades:{type:Array,required:true},completadas:{type:Object,default:()=>({})},mundoId:{type:String,required:true}})
const respuestas=ref({})
const resultados=ref({})
function comprobar(actividad) {
  const correcta = Number(respuestas.value[actividad.id]) === Number(actividad.respuesta)
  resultados.value = { ...resultados.value, [actividad.id]: correcta }
  emit('calificada', { actividadId: actividad.id, correcta })
  if (correcta) playCompletionSound()
}
function reiniciar(actividadId) {
  respuestas.value = { ...respuestas.value, [actividadId]: '' }
  resultados.value = { ...resultados.value, [actividadId]: undefined }
}
watch(()=>props.mundoId,()=>{respuestas.value={};resultados.value={}})
</script>
<style scoped>
